import sys

def main():
    X = int(sys.stdin.read().strip())

    left, right = 0, X

    while left <= right:
        mid = (left + right) // 2
        balance = 100 * (1 << mid)

        if balance >= X:
            right = mid - 1
        else:
            left = mid + 1

    print(left)

if __name__ == "__main__":
    main()
